// ─── Student API ─────────────────────────────────────────────────────────────

export const studentInterviewApi = {
  getAssignments: (status?: string) => {
    const qs = status ? `?status=${status}` : '';
    return apiFetch(`${MODULE_URL}/student/assignments${qs}`);
  },

  // Self-serve: published templates a student can practice on demand
  getPracticeTemplates: () => apiFetch(`${MODULE_URL}/student/practice-templates`),

  startAttempt: (templateId: string, assignmentId?: string, mode?: 'structured' | 'conversational') =>
    apiFetch(`${MODULE_URL}/student/attempts/start`, {
      method: 'POST',
      body: JSON.stringify({ templateId, assignmentId, mode }),
    }),

  // Live conversational turn — send the candidate's last answer, get the interviewer's next line
  converse: (attemptId: string, lastAnswer?: string) =>
    apiFetch(`${MODULE_URL}/student/attempts/${attemptId}/converse`, {
      method: 'POST',
      body: JSON.stringify({ lastAnswer }),
    }),

  // Voice/avatar config for the live UI (provider, interviewer name, avatar image)
  voiceConfig: () => apiFetch(`${MODULE_URL}/voice/config`),

  // Natural-voice TTS → audio Blob, or null when not configured (caller uses browser voice)
  ttsAudio: async (text: string): Promise<Blob | null> => {
    const r = await fetch(`${MODULE_URL}/voice/tts`, {
      method: 'POST', headers: getAuthHeaders(), body: JSON.stringify({ text }),
    });
    if (r.status === 204 || !r.ok) return null;
    return await r.blob();
  },

  // D-ID Streams talking-head proxy
  didCreate: () => apiFetch(`${MODULE_URL}/voice/did/stream`, { method: 'POST', body: '{}' }),
  didSdp: (streamId: string, answer: any, sessionId: string) =>
    apiFetch(`${MODULE_URL}/voice/did/stream/${streamId}/sdp`, { method: 'POST', body: JSON.stringify({ answer, sessionId }) }),
  didIce: (streamId: string, candidate: any, sessionId: string) =>
    apiFetch(`${MODULE_URL}/voice/did/stream/${streamId}/ice`, { method: 'POST', body: JSON.stringify({ candidate, sessionId }) }),
  didTalk: (streamId: string, sessionId: string, text: string) =>
    apiFetch(`${MODULE_URL}/voice/did/stream/${streamId}/talk`, { method: 'POST', body: JSON.stringify({ sessionId, text }) }),
  didClose: (streamId: string, sessionId: string) =>
    apiFetch(`${MODULE_URL}/voice/did/stream/${streamId}/close`, { method: 'POST', body: JSON.stringify({ sessionId }) }),

  getAttempts: (params?: { templateId?: string; status?: string; page?: number; limit?: number }) => {
    const qs = new URLSearchParams();
    if (params?.templateId) qs.append('templateId', params.templateId);
    if (params?.status) qs.append('status', params.status);
    if (params?.page) qs.append('page', String(params.page));
    if (params?.limit) qs.append('limit', String(params.limit));
    const q = qs.toString();
    return apiFetch(`${MODULE_URL}/student/attempts${q ? `?${q}` : ''}`);
  },

  getAttempt: (attemptId: string) =>
    apiFetch(`${MODULE_URL}/student/attempts/${attemptId}`),

  saveAnswer: (attemptId: string, data: {
    sectionIndex: number; questionIndex: number;
    answerText?: string; answerCode?: string;
    selectedMCQOption?: string; answerAudioUrl?: string;
    responseTimeSeconds?: number;
  }) =>
    apiFetch(`${MODULE_URL}/student/attempts/${attemptId}/answer`, {
      method: 'POST',
      body: JSON.stringify(data),
    }),

  skipQuestion: (attemptId: string, sectionIndex: number, questionIndex: number) =>
    apiFetch(`${MODULE_URL}/student/attempts/${attemptId}/skip`, {
      method: 'POST',
      body: JSON.stringify({ sectionIndex, questionIndex }),
    }),

  completeSection: (attemptId: string, sectionIndex: number) =>
    apiFetch(`${MODULE_URL}/student/attempts/${attemptId}/complete-section`, {
      method: 'POST',
      body: JSON.stringify({ sectionIndex }),
    }),

  submitAttempt: (attemptId: string) =>
    apiFetch(`${MODULE_URL}/student/attempts/${attemptId}/submit`, { method: 'POST' }),

  saveRecording: (attemptId: string, body: { bunnyVideoId?: string; bunnyLibraryId?: string | number; status?: string }) =>
    apiFetch(`${MODULE_URL}/student/attempts/${attemptId}/recording`, { method: 'POST', body: JSON.stringify(body) }),

  getReport: (attemptId: string) =>
    apiFetch(`${MODULE_URL}/student/attempts/${attemptId}/report`),

  getAnalytics: () =>
    apiFetch(`${MODULE_URL}/student/analytics`),

  /** Upload a per-question audio/video recording */
  uploadAnswerRecording: async (
    attemptId: string,
    blob: Blob,
    sectionIndex: number,
    questionIndex: number,
    responseTimeSeconds?: number
  ) => {
    const formData = new FormData();
    const ext = blob.type.includes('video') ? '.webm' : '.webm';
    formData.append('recording', blob, `answer-${sectionIndex}-${questionIndex}${ext}`);
    formData.append('sectionIndex', String(sectionIndex));
    formData.append('questionIndex', String(questionIndex));
    if (responseTimeSeconds !== undefined) {
      formData.append('responseTimeSeconds', String(responseTimeSeconds));
    }
    const token = localStorage.getItem('token');
    const tenantId = localStorage.getItem('tenantId');
    const headers: Record<string, string> = {};
    if (token) headers['Authorization'] = `Bearer ${token}`;
    if (tenantId) headers['X-Tenant-Id'] = tenantId;
    // Do NOT set Content-Type — browser sets multipart boundary automatically
    const response = await fetch(
      `${MODULE_URL}/student/attempts/${attemptId}/upload-answer`,
      { method: 'POST', headers, body: formData }
    );
    if (!response.ok) {
      const data = await response.json().catch(() => ({}));
      throw new Error(data.message || `Upload failed: ${response.status}`);
    }
    return response.json();
  },
};

